import { useRef, useState, useEffect, useCallback } from "react";
import styles from "./AudioRecorder.module.css";
import { WS_URL } from "./AudioRecorder.logic";

export type AudioRecorderProps = Readonly<{
  autoStart: boolean;
  threadId?: string;
  transcript?: string;
  onTranscriptionStart?: () => void;
  onTranscriptionComplete?: (text: string) => void;
  onTranscriptionError?: (error: string) => void;
  onAudioBlobComplete?: (blob: Blob) => void;
  onRecordingStateChange?: (isRecording: boolean) => void;
  setShowRecorder?: (show: boolean) => void;
  setAudioURL: (url: string) => void;
  title?: string;
  language: string;
}>;

const mergeTranscriptChunk = (previous: string, incoming: string) => {
  const prev = previous.trim();
  const next = incoming.trim();
  if (!next) return previous;
  if (!prev) return next;

  if (next.startsWith(prev)) return next;
  if (prev.startsWith(next)) return prev;

  return `${prev} ${next}`.replaceAll(/\s+/g, " ").trim();
};

export default function AudioRecorder({
  autoStart,
  transcript = "",
  onTranscriptionStart,
  onTranscriptionComplete,
  onTranscriptionError,
  onAudioBlobComplete,
  onRecordingStateChange,
  setShowRecorder,
  setAudioURL,
  language,
}: AudioRecorderProps) {
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const animFrameRef = useRef<number | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const streamRef = useRef<MediaStream | null>(null);

  const workletRef = useRef<AudioWorkletNode | null>(null); // ✅ NEW

  const [isRecording, setIsRecording] = useState(false);
  const [isPaused, setIsPaused] = useState(false);

  const [duration, setDuration] = useState(0);
  const [barHeights, setBarHeights] = useState(new Array(40).fill(2));

  const timerRef = useRef<number | null>(null);

  const wsRef = useRef<WebSocket | null>(null);
  const isRecordingRef = useRef<boolean>(false);
  const isPausedRef = useRef<boolean>(false);
  const transcriptRef = useRef<string>("");

  const stopResources = () => {
    if (wsRef.current) {
      wsRef.current.send(JSON.stringify({ type: "stop" }));
      setTimeout(() => wsRef.current?.close(), 100);
      wsRef.current = null;
    }

    // ❌ removed ScriptProcessor cleanup
    // ✅ AudioWorklet cleanup
    if (workletRef.current) {
      workletRef.current.disconnect();
      workletRef.current = null;
    }

    if (audioCtxRef.current) {
      audioCtxRef.current.close();
      audioCtxRef.current = null;
    }

    if (streamRef.current) {
      for (const t of streamRef.current.getTracks()) {
        t.stop();
      }
      streamRef.current = null;
    }
  };

  useEffect(() => {
    return () => {
      stopResources();
      if (animFrameRef.current !== null) {
        cancelAnimationFrame(animFrameRef.current);
      }
      if (timerRef.current !== null) {
        clearInterval(timerRef.current);
      }
    };
  }, []);

  useEffect(() => {
    if (!isRecordingRef.current) {
      transcriptRef.current = transcript;
    }
  }, [transcript]);

  const drawBars = () => {
    if (!analyserRef.current) return;

    const analyser = analyserRef.current;
    const data = new Uint8Array(analyser.frequencyBinCount);
    analyser.getByteFrequencyData(data);

    const bars = new Array(40).fill(0).map((_, i) => {
      const slice = Math.floor(data.length / 40);
      const start = i * slice;
      let sum = 0;

      for (let j = start; j < start + slice; j++) {
        sum += data[j];
      }

      const avg = sum / slice;
      return Math.max(2, (avg / 255) * 64);
    });

    setBarHeights(bars);
    animFrameRef.current = requestAnimationFrame(drawBars);
  };

  const startRecording = useCallback(async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      streamRef.current = stream;

      const audioCtx = new (
        globalThis.AudioContext ||
        (globalThis as unknown as Record<string, typeof AudioContext>)
          .webkitAudioContext
      )({
        sampleRate: 16000,
      });

      if (audioCtx.state === "suspended") {
        await audioCtx.resume();
      }

      audioCtxRef.current = audioCtx;

      const source = audioCtx.createMediaStreamSource(stream);
      sourceRef.current = source;

      const analyser = audioCtx.createAnalyser();
      analyser.fftSize = 256;
      analyserRef.current = analyser;

      source.connect(analyser);

      const ws = new WebSocket(WS_URL);
      wsRef.current = ws;

      transcriptRef.current = "";
      onTranscriptionStart?.();

      ws.onopen = () => {
        ws.send(
          JSON.stringify({
            type: "start",
            sampleRate: audioCtx.sampleRate,
            language,
          })
        );
      };

      ws.onerror = (err) => {
        console.error("WebSocket error:", err);
        onTranscriptionError?.("Connection error");
      };

      ws.onmessage = (event) => {
        try {
          const msg = JSON.parse(event.data);

          if (msg.type === "transcript") {
            const text =
              msg.data?.transcript ||
              msg.data?.text ||
              (typeof msg.data === "string" ? msg.data : null);

            if (text) {
              const merged = mergeTranscriptChunk(transcriptRef.current, text);
              transcriptRef.current = merged;
              onTranscriptionComplete?.(merged);
            }
          } else if (msg.type === "error") {
            onTranscriptionError?.(msg.message);
          }
        } catch (e) {
          console.error("WS parse error", e);
        }
      };

      // 🔥 AUDIO WORKLET (REPLACEMENT)
      await audioCtx.audioWorklet.addModule("/pcm-processor.js");

      const worklet = new AudioWorkletNode(audioCtx, "pcm-processor");
      workletRef.current = worklet;

      worklet.port.onmessage = (event) => {
        if (
          isRecordingRef.current &&
          !isPausedRef.current &&
          ws.readyState === WebSocket.OPEN
        ) {
          ws.send(event.data);
        }
      };

      source.connect(worklet);
      worklet.connect(audioCtx.destination);

      // MediaRecorder (UNCHANGED)
      const mediaRecorder = new MediaRecorder(stream, {
        mimeType: "audio/webm;codecs=opus",
      });

      mediaRecorderRef.current = mediaRecorder;
      chunksRef.current = [];

      mediaRecorder.ondataavailable = (e) => {
        chunksRef.current.push(e.data);
      };

      mediaRecorder.onstop = async () => {
        const blob = new Blob(chunksRef.current, {
          type: "audio/webm",
        });

        const url = URL.createObjectURL(blob);
        setAudioURL(url);

        onAudioBlobComplete?.(blob);

        setBarHeights(new Array(40).fill(2));

        if (animFrameRef.current !== null) {
          cancelAnimationFrame(animFrameRef.current);
        }
      };

      mediaRecorder.start();

      setIsRecording(true);
      onRecordingStateChange?.(true);

      isRecordingRef.current = true;
      setIsPaused(false);
      isPausedRef.current = false;

      setAudioURL("");
      setDuration(0);

      timerRef.current = globalThis.setInterval(() => {
        setDuration((d) => d + 1);
      }, 1000);

      drawBars();
    } catch (err) {
      console.error("Mic access denied", err);
      onTranscriptionError?.("Mic access denied");
    }
  }, [
    onTranscriptionStart,
    onTranscriptionComplete,
    onTranscriptionError,
    onRecordingStateChange,
    onAudioBlobComplete,
    setAudioURL,
    language,
  ]);

  const hasStartedRef = useRef(false);

  useEffect(() => {
    if (autoStart && !hasStartedRef.current) {
      hasStartedRef.current = true;
      startRecording();
    }
  }, [autoStart, startRecording]);

  const togglePause = () => {
    if (!mediaRecorderRef.current) return;

    if (isPaused) {
      mediaRecorderRef.current.resume();
      setIsPaused(false);
      isPausedRef.current = false;

      timerRef.current = globalThis.setInterval(
        () => setDuration((d) => d + 1),
        1000
      );

      drawBars();
    } else {
      mediaRecorderRef.current.pause();
      setIsPaused(true);
      isPausedRef.current = true;

      if (timerRef.current !== null) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }

      if (animFrameRef.current !== null) {
        cancelAnimationFrame(animFrameRef.current);
        animFrameRef.current = null;
      }

      setBarHeights(new Array(40).fill(2));
    }
  };

  const stopRecording = () => {
    mediaRecorderRef.current?.stop();

    if (streamRef.current) {
      for (const t of streamRef.current.getTracks()) {
        t.stop();
      }
    }

    stopResources();

    if (timerRef.current !== null) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }

    if (animFrameRef.current !== null) {
      cancelAnimationFrame(animFrameRef.current);
      animFrameRef.current = null;
    }

    setIsRecording(false);
    onRecordingStateChange?.(false);

    isRecordingRef.current = false;
    setIsPaused(false);
    isPausedRef.current = false;

    setShowRecorder?.(false);

    setTimeout(() => {
      if (!transcriptRef.current.trim()) {
        onTranscriptionComplete?.("");
      }
    }, 200);
  };

  const formatTime = (s: number) => {
    const m = Math.floor(s / 60)
      .toString()
      .padStart(2, "0");

    const sec = (s % 60).toString().padStart(2, "0");

    return `${m}:${sec}`;
  };

  const isActive = isRecording && !isPaused;

  return (
    <div className={styles.inlineRecorder}>
      <span className={styles.timerInline}>{formatTime(duration)}</span>

      <div className={styles.waveformInline}>
        {barHeights.map((h, i) => (
          <div
            key={`bar-${i}-${h}`}
            className={styles.barInline}
            style={{
              height: `${h}px`,
              opacity: isActive ? 0.85 : 0.2,
              background: isPaused ? "#f5a623" : "#ff3c3c",
            }}
          />
        ))}
      </div>

      <button
        className={`${styles.btn} ${styles.btnRecord}`}
        onClick={isRecording ? stopRecording : startRecording}
      >
        {isRecording ? "■ Stop" : "● Record"}
      </button>

      <button
        className={`${styles.btn} ${styles.btnPause}`}
        onClick={togglePause}
        disabled={!isRecording}
      >
        {isPaused ? "▶ Resume" : "⏸ Pause"}
      </button>
    </div>
  );
}

import React, { useRef, useEffect, useState } from "react";
import styles from "./OrderForm.module.css";
import { Download, Mic, Square } from "lucide-react";
import { pdf } from "@react-pdf/renderer";
import OrderDocument from "./OrderDocument";
import { initialOrderData } from "./OrderForm.logic";
import { getTranslation, LANGUAGE_OPTIONS } from "../../constants/translations";
import { useTranscriber } from "../../hooks/useTranscriber";

export type OrderData = {
  header: {
    court_name: string;
    case_number: string;
    case_type: string;
    location: string;
    dates: {
      filing_date: string;
      registration_date: string;
      decision_date: string;
      other_dates: string[];
    };
  };
  case_title: {
    petitioner: string;
    respondent: string;
    full_title_text: string;
  };
  parties: {
    petitioners: string[];
    respondents: string[];
    accused: string[];
    complainant: string[];
    other_parties: string[];
  };
  advocates: {
    petitioner_side: string[];
    respondent_side: string[];
    government_side: string[];
    other: string[];
  };
  appearance_mode: string;
  case_details: {
    acts_sections: string;
    case_category: string;
    police_station: string;
    property_details: string;
    other_details: string;
  };
  procedural_history: string;
  issues_framed: string;
  evidence: {
    oral_evidence: string;
    documentary_evidence: string;
  };
  arguments: string;
  reasoning_points: string[];
  operative_order: {
    full_text: string;
    directions: string[];
    final_outcome: string;
  };
  final_order: string;
  signature: {
    judge_name: string;
    designation: string;
    court: string;
    date: string;
    place: string;
  };
  raw_text: string;
};

interface Props {
  data: OrderData | null;
  onUpdate: (data: OrderData) => void;
  isProcessing?: boolean;
  language?: string;
  onLanguageChange: (lang: string) => void;
  isMobile?: boolean;
}

const AutoResizeTextarea: React.FC<{
  value: string;
  onChange: (val: string) => void;
  placeholder: string;
  className: string;
}> = ({ value, onChange, placeholder, className }) => {
  const ref = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    if (ref.current) {
      ref.current.style.height = "auto";
      ref.current.style.height = ref.current.scrollHeight + "px";
    }
  }, [value]);

  return (
    <textarea
      ref={ref}
      className={className}
      value={value || ""}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      rows={1}
    />
  );
};

const OrderForm: React.FC<Props> = ({
  data,
  onUpdate,
  isProcessing,
  language,
  onLanguageChange,
  isMobile,
}) => {
  const [showLanguageMenu, setShowLanguageMenu] = useState(false);
  const t = getTranslation(language || "gu-IN");
  const containerRef = useRef<HTMLDivElement>(null);
  const formData = data || initialOrderData;
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);
  const [recordingField, setRecordingField] = useState<{
    path: string[];
    isNew: boolean;
  } | null>(null);

  const { isRecording, transcript, start, stop } = useTranscriber();

  const handleToggleVoice = async (path: string[], isNew: boolean) => {
    if (isRecording) {
      if (
        recordingField?.path.join(",") === path.join(",") &&
        recordingField?.isNew === isNew
      ) {
        stop();
        finalizeTranscription();
      } else {
        stop();
        finalizeTranscription();
        setRecordingField({ path, isNew });
        await start(language || "gu-IN");
      }
    } else {
      setRecordingField({ path, isNew });
      await start(language || "gu-IN");
    }
  };

  const appendToArrayAtPath = (path: string[], value: string) => {
    const newData = structuredClone(formData);
    let current = newData as unknown as Record<string, unknown>;

    for (const [i, key] of path.entries()) {
      if (i === path.length - 1) {
        if (!Array.isArray(current[key])) current[key] = [];
        (current[key] as string[]).push(value);
      } else {
        if (!current[key]) current[key] = {};
        current = current[key] as Record<string, unknown>;
      }
    }

    return newData;
  };

  const finalizeTranscription = () => {
    if (!recordingField) return;

    const { path, isNew } = recordingField;
    const text = transcript.trim();

    if (text) {
      if (isNew) {
        onUpdate(appendToArrayAtPath(path, text));
      } else {
        handleChange(path, text);
      }
    }

    setRecordingField(null);
  };

  useEffect(() => {
    if (!isRecording && recordingField) {
      finalizeTranscription();
    }
  }, [isRecording]);

  const handleGeneratePDF = async () => {
    setIsGeneratingPdf(true);
    try {
      const doc = (
        <OrderDocument data={formData} language={language || "gu-IN"} />
      );

      const blob = await pdf(doc).toBlob();
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `order-${formData.header.case_number || Date.now()}.pdf`;
      link.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error("PDF generation error:", err);
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  const handleChange = (path: string[], value: string | string[]) => {
    const newData = structuredClone(formData);
    let current = newData as unknown as Record<string, unknown>;

    for (let i = 0; i < path.length - 1; i++) {
      const key = path[i];
      if (!current[key]) current[key] = {};
      current = current[key] as Record<string, unknown>;
    }

    const lastKey = path.at(-1);
    if (lastKey) {
      current[lastKey] = value;
      onUpdate(newData);
    }
  };

  const safeJoinArray = (arr: unknown): string => {
    if (!arr || !Array.isArray(arr)) return "";
    return arr
      .map((item) => {
        if (typeof item === "string") return item;
        if (typeof item === "object" && item !== null) {
          const obj = item as Record<string, unknown>;
          return (
            obj.name || obj.advocate_name || obj.text || JSON.stringify(item)
          ) as string;
        }
        return String(item);
      })
      .join(", ");
  };

  const renderInline = (
    value: string | undefined,
    path: string[],
    placeholder: string
  ) => {
    return (
      <AutoResizeTextarea
        className={styles.docInlineTextarea}
        value={value || ""}
        onChange={(v) => handleChange(path, v)}
        placeholder={placeholder}
      />
    );
  };

  const renderTextArea = (
    value: string | undefined,
    path: string[],
    placeholder: string
  ) => {
    return (
      <AutoResizeTextarea
        className={styles.docTextarea}
        value={value || ""}
        onChange={(v) => handleChange(path, v)}
        placeholder={placeholder}
      />
    );
  };

  return (
    <div className={styles.wrapper}>
      <div className={styles.toolbar}>
        <h3>{t.order_title}</h3>
        <div className={styles.statusGroup}>
          {isMobile ? (
            <>
              <button
                type="button"
                className={styles.languageInline}
                onClick={() => setShowLanguageMenu(true)}
              >
                {LANGUAGE_OPTIONS.find((opt) => opt.value === language)
                  ?.label || "English"}
              </button>
              {showLanguageMenu && (
                <>
                  <button
                    type="button"
                    className={styles.languageMenuBackdrop}
                    onClick={() => setShowLanguageMenu(false)}
                    aria-label="Close language menu"
                  />
                  <div className={styles.languageMenuSheet}>
                    {LANGUAGE_OPTIONS.map((option) => (
                      <button
                        key={option.value}
                        type="button"
                        className={`${styles.languageMenuItem} ${
                          option.value === language
                            ? styles.languageMenuItemActive
                            : ""
                        }`}
                        onClick={() => {
                          onLanguageChange(option.value);
                          setShowLanguageMenu(false);
                        }}
                      >
                        {option.label}
                      </button>
                    ))}
                  </div>
                </>
              )}
            </>
          ) : (
            <select
              className={styles.languageSelect}
              value={language || "gu-IN"}
              onChange={(e) => onLanguageChange(e.target.value)}
            >
              {LANGUAGE_OPTIONS.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
          )}

          {isProcessing && (
            <span className={styles.processingBadge}>{t.filling_order}</span>
          )}
          <button
            className={styles.pdfButton}
            onClick={() => onUpdate(initialOrderData)}
            type="button"
            title="Reset the form to its initial state"
          >
            {t.reset_form}
          </button>
          <button
            className={styles.pdfButton}
            onClick={handleGeneratePDF}
            disabled={isGeneratingPdf}
            aria-busy={isGeneratingPdf}
            type="button"
            title="Generates a multi-page PDF (handles overflow)"
          >
            <Download size={16} />
            {isGeneratingPdf ? t.generating : t.save_pdf}
          </button>
        </div>
      </div>

      <div className={styles.formContainer}>
        {isProcessing && (
          <div className={styles.loaderOverlay}>
            <div className={styles.spinner}></div>
            <span>{t.filling_order}</span>
          </div>
        )}
        {/* Printable Page Layout */}
        <div className={styles.documentPage} ref={containerRef}>
          <div className={styles.pageHeader}>
            <div className={styles.caseNoTop}>
              {formData.header?.case_number}
            </div>
          </div>

          <div className={styles.courtNameSection}>
            <h2>
              <AutoResizeTextarea
                className={styles.docInlineTextareaCenter}
                value={formData.header?.court_name || ""}
                onChange={(v) => handleChange(["header", "court_name"], v)}
                placeholder={t.court_name}
              />
            </h2>
            <h3>
              <AutoResizeTextarea
                className={styles.docInlineTextareaCenter}
                value={formData.header?.location || ""}
                onChange={(v) => handleChange(["header", "location"], v)}
                placeholder={t.location}
              />
            </h3>
          </div>

          <div className={styles.caseTypeSection}>
            <h4>
              <AutoResizeTextarea
                className={styles.docInlineTextareaCenter}
                value={formData.header?.case_type || ""}
                onChange={(v) => handleChange(["header", "case_type"], v)}
                placeholder={t.case_type}
              />
              &nbsp;NO.&nbsp;
              <AutoResizeTextarea
                className={styles.docInlineTextareaCenter}
                value={formData.header?.case_number || ""}
                onChange={(v) => handleChange(["header", "case_number"], v)}
                placeholder={t.case_number}
              />
            </h4>
          </div>

          {/* Dates Section */}
          <div className={styles.datesSection}>
            <div className={styles.dateRow}>
              <span>{t.filing_date}:</span>

              {renderInline(
                formData.header?.dates?.filing_date,
                ["header", "dates", "filing_date"],
                "DD/MM/YYYY"
              )}
            </div>
            <div className={styles.dateRow}>
              <span>{t.registration_date}:</span>

              {renderInline(
                formData.header?.dates?.registration_date,
                ["header", "dates", "registration_date"],
                "DD/MM/YYYY"
              )}
            </div>
            <div className={styles.dateRow}>
              <span>{t.decision_date}:</span>
              {renderInline(
                formData.header?.dates?.decision_date,
                ["header", "dates", "decision_date"],
                "DD/MM/YYYY"
              )}
            </div>
          </div>

          <div className={styles.partiesSection}>
            <div className={styles.partyRow}>
              <div className={styles.partyDetails}>
                {renderTextArea(
                  formData.case_title?.petitioner,
                  ["case_title", "petitioner"],
                  `${t.petitioner} ${t.full_name_address}`
                )}
              </div>
              <div className={styles.partyRole}>{t.petitioner}</div>
            </div>

            <div className={styles.vsText}>{t.versus}</div>

            <div className={styles.partyRow}>
              <div className={styles.partyDetails}>
                {renderTextArea(
                  formData.case_title?.respondent,
                  ["case_title", "respondent"],
                  `${t.respondent} ${t.full_name_address}`
                )}
              </div>
              <div className={styles.partyRole}>{t.respondent}</div>
            </div>
          </div>

          <hr className={styles.divider} />

          {/* Parties Detail Section */}
          {(formData.parties?.complainant?.length > 0 ||
            formData.parties?.accused?.length > 0 ||
            formData.parties?.other_parties?.length > 0) && (
            <div className={styles.partiesDetailSection}>
